19	// DEVDESK-470 task 470.4: Trace Path opens a sub-level of the Diagnostics tab
20	// (StateTrace) that reuses the Path tab's model (m.pathModel). No test runs a
21	// real trace: the engine is a fakeEngine and the messages are fed by hand.
22	
23	const traceLevelHost = "example.com"
24	
25	// traceLevelModel returns a model that pressed Trace Path on traceLevelHost,
26	// with the Cmd that enter returned.
27	func traceLevelModel(t *testing.T, host string) (*Model, *fakeEngine, tea.Cmd) {
28		t.Helper()
29		m, fe := traceFormModel(t, true)
30		fe.resolveFn = func(context.Context, string) ([]netip.Addr, error) {
31			return []netip.Addr{netip.MustParseAddr("93.184.216.34")}, nil
32		}
33		m.targetInput.SetValue(host)
34		m.focusedField = fieldTraceButton
35		m, cmd := step(t, m, testutil.Key("enter"))
36		return m, fe, cmd
37	}
38	
39	// traceHops feeds n router hops of the current run.
40	func traceHops(t *testing.T, m *Model, n int) *Model {
41		t.Helper()
42		for ttl := 1; ttl <= n; ttl++ {
43			m = feed(t, m, pathHopMsg{gen: m.pathModel.gen, hop: hopOf(ttl, nettrace.HopRouter)})
44		}
45		return m
46	}
47	
48	func traceEnded(t *testing.T, m *Model) *Model {
49		t.Helper()
50		return feed(t, m, pathDoneMsg{gen: m.pathModel.gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached}})
51	}
52	
53	func traceCanceled(t *testing.T, m *Model) *Model {
54		t.Helper()
55		return feed(t, m, testutil.Key("esc"))
56	}
57	
58	// tracePhases returns one fresh model per phase of a trace, so no case sees the
59	// mutations of another (a Model is updated in place).
60	func tracePhases(t *testing.T) map[string]*Model {
61		t.Helper()
62		build := func(end func(*testing.T, *Model) *Model) *Model {
63			m, _, _ := traceLevelModel(t, traceLevelHost)
64			m = traceHops(t, m, 2)
65			if end == nil {
66				return m
67			}
68			return end(t, m)
69		}
70		return map[string]*Model{
71			"running":  build(nil),
72			"done":     build(traceEnded),
73			"canceled": build(traceCanceled),
74		}
75	}
