87	func TestPathModelStartFromFormPrefillsThenLaunches(t *testing.T) {
88		pm, fe := newPM(t)
89		fe.resolveFn = func(context.Context, string) ([]netip.Addr, error) {
90			return []netip.Addr{netip.MustParseAddr("1.1.1.1")}, nil
91		}
92		pm.errText = "stale"
93		gen := pm.gen
94	
95		cmd := pm.startFromForm(pathTarget{Host: "one.one.one.one"})
96	
97		if !pm.running() || pm.gen != gen+1 {
98			t.Fatalf("running=%v gen %d->%d, want a launched run", pm.running(), gen, pm.gen)
99		}
100		if got := pm.input.Value(); got != "one.one.one.one" {
101			t.Errorf("field = %q, want the host prefilled", got)
102		}
103		if pm.target.Host != "one.one.one.one" || pm.errText != "" {
104			t.Errorf("target=%q errText=%q, want the new target and no stale error", pm.target.Host, pm.errText)
105		}
106		if cmd == nil {
107			t.Fatal("startFromForm returned no Cmd: the trace would never start")
108		}
109		_ = testutil.Msgs(cmd)
110		if fe.traceCalls != 1 {
111			t.Errorf("trace calls = %d after running the Cmd, want 1", fe.traceCalls)
112		}
113	}
