125	func TestTraceLevelEnterOpensTheSubLevelAndStartsTheTrace(t *testing.T) {
126		m, fe, cmd := traceLevelModel(t, traceLevelHost)
127	
128		if m.state != StateTrace {
129			t.Fatalf("state = %v, want StateTrace", m.state)
130		}
131		if m.activeTab != tabDiagnostics {
132			t.Errorf("activeTab = %d, want the Diagnostics tab", m.activeTab)
133		}
134		if !m.pathModel.running() || m.pathModel.target.Host != traceLevelHost {
135			t.Errorf("running=%v target=%q, want a run on %q", m.pathModel.running(), m.pathModel.target.Host, traceLevelHost)
136		}
137		if !m.Running() {
138			t.Error("Running() = false: the router could rebuild the view mid-trace")
139		}
140		if m.traceValidation.Invalid(traceKeyTarget) {
141			t.Error("an accepted trace left the target marked invalid")
142		}
143	
144		if fe.traceCalls != 0 {
145			t.Fatalf("trace ran inside Update (%d calls): it belongs to the Cmd (Rule 110)", fe.traceCalls)
146		}
147		msgs := testutil.Msgs(cmd)
148		if fe.traceCalls != 1 || fe.resolveHost != traceLevelHost {
149			t.Errorf("trace calls=%d host=%q after the Cmd, want 1 on %q", fe.traceCalls, fe.resolveHost, traceLevelHost)
150		}
151		if len(msgs) == 0 {
152			t.Fatal("the Cmd produced no message for Update")
153		}
154		m = feed(t, m, msgs...)
155		if m.state != StateTrace {
156			t.Errorf("state = %v after the first messages, want StateTrace", m.state)
157		}
158	}
