280	// esc while tracing cancels; a second esc goes back to the form.
281	func TestTraceLevelEscCancelsThenGoesBackToTheForm(t *testing.T) {
282		m, _, _ := traceLevelModel(t, traceLevelHost)
283		m.portInput.SetValue("8443")
284		m.dnsServerInput.SetValue("9.9.9.9")
285		m.results = netcheck.ResultsOf(check(netcheck.CheckResolve, netcheck.OK, "kept"))
286		m = traceHops(t, m, 2)
287		gen := m.pathModel.gen
288	
289		m = feed(t, m, testutil.Key("esc"))
290		if m.state != StateTrace {
291			t.Fatalf("state = %v after the first esc, want StateTrace", m.state)
292		}
293		pm := m.pathModel
294		if pm.running() || pm.result == nil || pm.result.Outcome != nettrace.OutcomeCancelled {
295			t.Errorf("running=%v result=%+v, want a canceled run", pm.running(), pm.result)
296		}
297		if pm.gen == gen {
298			t.Error("the run's generation did not change: its late messages would still land")
299		}
300		if got := pmHopTTLs(pm); !slices.Equal(got, []int{1, 2}) {
301			t.Errorf("hops = %v after cancel, want [1 2] kept", got)
302		}
303		if m.Running() {
304			t.Error("Running() = true after the cancel")
305		}
306	
307		m = feed(t, m, testutil.Key("esc"))
308		if m.state != StateInput {
309			t.Fatalf("state = %v after the second esc, want StateInput", m.state)
310		}
311		assertFormKept(t, m)
312	}
