314	// assertFormKept checks what going back to the form must not lose.
315	func assertFormKept(t *testing.T, m *Model) {
316		t.Helper()
317		if got := m.targetInput.Value(); got != traceLevelHost {
318			t.Errorf("Target = %q, want %q kept", got, traceLevelHost)
319		}
320		if got := m.portInput.Value(); got != "8443" {
321			t.Errorf("Port = %q, want 8443 kept", got)
322		}
323		if got := m.dnsServerInput.Value(); got != "9.9.9.9" {
324			t.Errorf("DNS = %q, want 9.9.9.9 kept", got)
325		}
326		if m.focusedField != fieldTraceButton {
327			t.Errorf("focusedField = %d, want the Trace Path button (%d)", m.focusedField, fieldTraceButton)
328		}
329		if m.targetInput.Focused() {
330			t.Error("the target field has the focus while the button is focused")
331		}
332		if len(m.results.All()) != 1 {
333			t.Error("going back reset the Diagnostics results: it must not call resetToForm")
334		}
335		if m.InEditMode() {
336			t.Error("InEditMode() = true with the button focused")
337		}
338	}
