340	// Done and canceled are the same screen for the keys.
341	func TestTraceLevelKeysAreTheSameWhenDoneAndWhenCanceled(t *testing.T) {
342		ends := map[string]func(*testing.T, *Model) *Model{
343			"done":     func(t *testing.T, m *Model) *Model { return traceEnded(t, traceHops(t, m, 2)) },
344			"canceled": func(t *testing.T, m *Model) *Model { return traceCanceled(t, traceHops(t, m, 2)) },
345		}
346		for name, end := range ends {
347			t.Run(name+"/esc goes back", func(t *testing.T) {
348				m, _, _ := traceLevelModel(t, traceLevelHost)
349				m.portInput.SetValue("8443")
350				m.dnsServerInput.SetValue("9.9.9.9")
351				m.results = netcheck.ResultsOf(check(netcheck.CheckResolve, netcheck.OK, "kept"))
352				m = feed(t, end(t, m), testutil.Key("esc"))
353				if m.state != StateInput {
354					t.Fatalf("state = %v, want StateInput", m.state)
355				}
356				assertFormKept(t, m)
357			})
358	
359			for _, key := range []string{"enter", "ctrl+r", "ctrl+o"} {
360				t.Run(name+"/"+key+" does nothing", func(t *testing.T) {
361					m, fe, _ := traceLevelModel(t, traceLevelHost)
362					m = end(t, m)
363					gen, calls := m.pathModel.gen, fe.traceCalls
364	
365					m, cmd := step(t, m, testutil.Key(key))
366	
367					if m.state != StateTrace || m.pathModel.running() || m.pathModel.gen != gen {
368						t.Errorf("state=%v running=%v gen %d->%d, want the finished trace untouched", m.state, m.pathModel.running(), gen, m.pathModel.gen)
369					}
370					if m.pathModel.pickerOpen() {
371						t.Error("ctrl+o opened the source selector: the sub-level has no relaunch or source choice")
372					}
373					if msgs := testutil.Msgs(cmd); len(msgs) != 0 || fe.traceCalls != calls {
374						t.Errorf("msgs=%v trace calls %d->%d, want none", msgs, calls, fe.traceCalls)
375					}
376					if got := pmHopTTLs(m.pathModel); !slices.Equal(got, []int{1, 2}) {
377						t.Errorf("hops = %v, want [1 2] kept", got)
378					}
379				})
380			}
381		}
382	}
