422	func TestTraceLevelShortcuts(t *testing.T) {
423		m, _, _ := traceLevelModel(t, traceLevelHost)
424	
425		running := m.GetShortcuts()
426		if got := testutil.ShortcutKeys(running); !slices.Equal(got, []string{"esc"}) {
427			t.Fatalf("running shortcuts = %v, want [esc] alone", got)
428		}
429		if running[0].Description != "Cancel the trace" || running[0].Disabled {
430			t.Errorf("running esc = %+v, want an enabled %q", running[0], "Cancel the trace")
431		}
432	
433		for name, mm := range tracePhases(t) {
434			if name == "running" {
435				continue
436			}
437			sc := mm.GetShortcuts()
438			if got := testutil.ShortcutKeys(sc); !slices.Equal(got, []string{"tab", "esc", "?"}) {
439				t.Errorf("%s: shortcuts = %v, want [tab esc ?]", name, got)
440				continue
441			}
442			if sc[1].Description != "Back to the form" {
443				t.Errorf("%s: esc says %q, want %q", name, sc[1].Description, "Back to the form")
444			}
445			for _, k := range []string{"enter", "ctrl+r", "ctrl+o"} {
446				if testutil.HasShortcut(sc, k) {
447					t.Errorf("%s: %s is advertised but does nothing here", name, k)
448				}
449			}
450			if !testutil.ShortcutEnabled(sc, "esc") || !testutil.ShortcutEnabled(sc, "tab") {
451				t.Errorf("%s: tab and esc must be enabled", name)
452			}
453		}
454	
455		phases := tracePhases(t)
456		done, cancel := phases["done"].GetShortcuts(), phases["canceled"].GetShortcuts()
457		if !slices.Equal(testutil.ShortcutKeys(done), testutil.ShortcutKeys(cancel)) {
458			t.Errorf("done %v and canceled %v advertise different keys", testutil.ShortcutKeys(done), testutil.ShortcutKeys(cancel))
