499	// The Path model's target field is hidden in the sub-level. Letters, pastes and
500	// the keys of a form must not reach it, in any state of the run.
501	func TestTraceLevelLettersDoNotReachTheHiddenField(t *testing.T) {
502		typed := append(testutil.Type("abcXYZ:"), testutil.Key("backspace"), testutil.Paste("pasted"))
503		ends := map[string]func(*testing.T, *Model) *Model{
504			"running":  func(_ *testing.T, m *Model) *Model { return m },
505			"done":     traceEnded,
506			"canceled": traceCanceled,
507		}
508		for name, end := range ends {
509			t.Run(name, func(t *testing.T) {
510				m, _, _ := traceLevelModel(t, traceLevelHost)
511				m = end(t, traceHops(t, m, 1))
512				footer := m.footer.Text()
513	
514				m = feed(t, m, typed...)
515	
516				if got := m.pathModel.input.Value(); got != traceLevelHost {
517					t.Errorf("hidden field = %q, want %q untouched", got, traceLevelHost)
518				}
519				if got := m.targetInput.Value(); got != traceLevelHost {
520					t.Errorf("form target = %q, want %q untouched", got, traceLevelHost)
521				}
522				if m.state != StateTrace || m.footer.Text() != footer {
523					t.Errorf("state=%v footer=%q, want nothing to react to a letter", m.state, m.footer.Text())
524				}
525				if m.InEditMode() {
526					t.Error("InEditMode() = true: the sub-level has no field to edit")
527				}
528			})
529		}
530	}
531	
532	// handleDoneError puts the Path model back to editing; in the sub-level that
533	// must not turn its hidden field into a live one.
534	func TestTraceLevelAFailedRunDoesNotLeakTheKeyboardToTheHiddenField(t *testing.T) {
535		m, _, _ := traceLevelModel(t, traceLevelHost)
536		m = feed(t, m, pathDoneMsg{gen: m.pathModel.gen, err: context.DeadlineExceeded})
537	
538		m = feed(t, m, testutil.Type("abcXYZ")...)
539		if got := m.pathModel.input.Value(); got != traceLevelHost {
540			t.Errorf("hidden field = %q after a failed run, want %q untouched", got, traceLevelHost)
541		}
542		if m.InEditMode() {
543			t.Error("InEditMode() = true after a failed run: the router would swallow ':' and the keys")
544		}
545		if m.Running() {
546			t.Error("Running() = true after a failed run")
547		}
548	
549		m = feed(t, m, testutil.Key("esc"))
550		if m.state != StateInput {
551			t.Errorf("state = %v after esc on a failed run, want StateInput: the user must not be stranded", m.state)
552		}
553	}
554	
555	func TestTraceLevelSurvivesALeaveAndReturn(t *testing.T) {
556		for name, prep := range map[string]func(*testing.T, *Model) *Model{
557			"running": func(_ *testing.T, m *Model) *Model { return m },
558			"done":    traceEnded,
559		} {
560			t.Run(name, func(t *testing.T) {
561				m, _, _ := traceLevelModel(t, traceLevelHost)
562				m = prep(t, traceHops(t, m, 2))
563				title := tracePlainTitle(m)
564	
565				m = feed(t, m, testutil.Key("tab"))
566				if m.activeTab != tabPorts {
567					t.Fatalf("activeTab = %d, want Ports", m.activeTab)
568				}
569				if got := tracePlainTitle(m); got != title && strings.Contains(got, "Path ") {
570					t.Errorf("another tab shows the sub-level title %q", got)
571				}
572				m = feed(t, m, testutil.Key("shift+tab"))
573	
574				if m.activeTab != tabDiagnostics || m.state != StateTrace {
575					t.Fatalf("tab=%d state=%v, want the sub-level back", m.activeTab, m.state)
576				}
577				if got := tracePlainTitle(m); got != title {
578					t.Errorf("title = %q, want %q", got, title)
579				}
580				if got, want := m.Render(), m.pathModel.table.View(); got != want {
581					t.Error("Render() is not the trace table after returning")
582				}
583				if got := pmHopTTLs(m.pathModel); !slices.Equal(got, []int{1, 2}) {
584					t.Errorf("hops = %v, want [1 2] kept", got)
585				}
586				if got := m.GetFooterHeight(); got != 3 {
587					t.Errorf("GetFooterHeight() = %d, want 3", got)
588				}
589			})
590		}
591	}
592	
593	// A trace goes on from the other tabs: its hops keep landing in the table.
594	func TestTraceLevelHopsKeepArrivingFromAnotherTab(t *testing.T) {
595		m, _, _ := traceLevelModel(t, traceLevelHost)
596		m = feed(t, m, testutil.Key("tab"))
597		m = traceHops(t, m, 2)
598		m = feed(t, m, testutil.Key("shift+tab"))
599		if got := pmHopTTLs(m.pathModel); !slices.Equal(got, []int{1, 2}) {
600			t.Errorf("hops = %v, want [1 2]", got)
601		}
602	}
603	
604	// A second trace from the form works after coming back.
605	func TestTraceLevelCanTraceAgainAfterGoingBack(t *testing.T) {
606		m, fe, _ := traceLevelModel(t, traceLevelHost)
607		m = traceHops(t, m, 2)
608		m = traceCanceled(t, m)
609		m = feed(t, m, testutil.Key("esc"))
610		gen := m.pathModel.gen
611	
612		m, cmd := step(t, m, testutil.Key("enter"))
613		if m.state != StateTrace || !m.pathModel.running() || m.pathModel.gen == gen {
614			t.Fatalf("state=%v running=%v gen %d->%d, want a new run", m.state, m.pathModel.running(), gen, m.pathModel.gen)
615		}
616		if got := pmHopTTLs(m.pathModel); len(got) != 0 {
617			t.Errorf("hops = %v, want the previous run's rows cleared", got)
618		}
619		_ = testutil.Msgs(cmd)
620		if fe.traceCalls != 1 {
621			t.Errorf("trace calls = %d, want 1 for the second run", fe.traceCalls)
622		}
623	}
624	
625	// Rule 116 for the sub-level: the table fills the viewport at any width, and its
626	// height follows the router's, which hands the view 2 lines more than on the
627	// Path tab (footer of 3 lines instead of 5).
628	func TestTraceLevelTableFillsTheViewport(t *testing.T) {
629		const window = 40
630		for _, w := range []int{120, 60} {
631			m, _, _ := traceLevelModel(t, traceLevelHost)
632			m = traceHops(t, m, 3)
633	
634			m = feed(t, m, tea.WindowSizeMsg{Width: w, Height: window - 3})
635			if got, want := m.pathModel.table.RenderedWidth(), w-2; got != want {
636				t.Errorf("width %d: RenderedWidth() = %d, want %d", w, got, want)
637			}
638			three := strings.Count(m.Render(), "\n")
639	
640			m = feed(t, m, tea.WindowSizeMsg{Width: w, Height: window - 5})
641			five := strings.Count(m.Render(), "\n")
642	
643			if three-five != 2 {
644				t.Errorf("width %d: table is %d lines with a 3-line footer and %d with 5, want exactly 2 more", w, three+1, five+1)
645			}
646		}
647	}
648	
649	// The sub-level and the Path tab size their table the same way for the same
650	// viewport.
651	func TestTraceLevelTableSizeMatchesThePathTab(t *testing.T) {
652		m, _, _ := traceLevelModel(t, traceLevelHost)
653		m = feed(t, m, tea.WindowSizeMsg{Width: 100, Height: 30})
654		pm, _ := newPM(t)
655		pm.resize(100, 30)
656		if got, want := strings.Count(m.Render(), "\n"), strings.Count(pm.view(), "\n"); got != want {
657			t.Errorf("sub-level table has %d line breaks, the Path tab's has %d at the same size", got, want)
658		}
659	}
